mapper.select:
SELECT COALESCE(SUM(COALESCE(t1.BFIL_AEK, 0) + COALESCE(t1.UP_AEK, 0) - COALESCE(t1.DW_AEK, 0)), 0)             AS balAek
     , COALESCE(SUM(COALESCE(t1.WON_BFIL_AEK, 0) + COALESCE(t1.WON_UP_AEK, 0) - COALESCE(t1.WON_DW_AEK, 0)), 0) AS wonBalAek
     , COALESCE(SUM(COALESCE(t1.FCUR_BFIL_AEK, 0) + COALESCE(t1.FCUR_UP_AEK, 0) - COALESCE(t1.FCUR_DW_AEK, 0)), 0) AS fcurBalAek
  FROM SYT0MC t1
 WHERE t1.CORP_GR  = #{corpGr}
   AND t1.TR_YMD   = TO_DATE(REPLACE(#{workDate}, '-', ''), 'YYYYMMDD')
   AND t1.FUND_CD  = #{fundCd}
   AND t1.TR_CD    = CASE #{trCd}
                         WHEN 'H21' THEN 'P40'
                         WHEN 'H22' THEN 'P41'
                     END
   AND t1.TRUSTEE  = #{trustee}
   AND t1.CURRENCY = #{currency}

SELECT CURRENCY
  FROM SYX2MM
 WHERE CORP_GR = #{corpGr}
   AND TRUSTEE = #{trustee}
 FETCH FIRST 1 ROWS ONLY

SELECT GIJUN_RT
  FROM SYX1HY
 WHERE CORP_GR   = #{corpGr}
   AND GIJUN_YMD = TO_DATE(REPLACE(#{gijunYmd}, '-', ''), 'YYYYMMDD')
   AND CURRENCY  = #{currency}
 FETCH FIRST 1 ROWS ONLY

mapper.insert:
INSERT INTO SYT0MA (
    CORP_GR
  , TR_YMD
  , TR_CD
  , FUND_CD
  , TRUSTEE
  , CURRENCY
  , TR_SEQ
  , TR_AEK
  , WON_TR_AEK
  , BAL_AEK
  , WON_BAL_AEK
  , TAX_AEK
  , GYULJE_YMD
  , FCUR_TR_AEK
  , FCUR_BAL_AEK
) VALUES (
    #{corpGr, jdbcType=VARCHAR}
  , TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
  , #{trCd, jdbcType=VARCHAR}
  , #{fundCd, jdbcType=VARCHAR}
  , #{trustee, jdbcType=VARCHAR}
  , #{currency, jdbcType=VARCHAR}
  , COALESCE(#{trSeq, jdbcType=NUMERIC}, 1)
  , COALESCE(#{trAek, jdbcType=NUMERIC}, 0)
  , COALESCE(#{wonTrAek, jdbcType=NUMERIC}, 0)
  , COALESCE(#{balAek, jdbcType=NUMERIC}, 0)
  , COALESCE(#{wonBalAek, jdbcType=NUMERIC}, 0)
  , #{taxAek, jdbcType=NUMERIC}
  , TO_DATE(REPLACE(#{gyuljeYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
  , #{fcurTrAek, jdbcType=NUMERIC}
  , #{fcurBalAek, jdbcType=NUMERIC}
)

mapper.update:
UPDATE SYT0MA
   SET FUND_CD      = #{fundCd, jdbcType=VARCHAR}
     , TRUSTEE      = #{trustee, jdbcType=VARCHAR}
     , CURRENCY     = #{currency, jdbcType=VARCHAR}
     , TR_SEQ       = COALESCE(#{trSeq, jdbcType=NUMERIC}, TR_SEQ)
     , GYULJE_YMD   = TO_DATE(REPLACE(#{gyuljeYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
     , TR_AEK       = COALESCE(#{trAek, jdbcType=NUMERIC}, 0)
     , WON_TR_AEK   = COALESCE(#{wonTrAek, jdbcType=NUMERIC}, 0)
     , BAL_AEK      = COALESCE(#{balAek, jdbcType=NUMERIC}, 0)
     , WON_BAL_AEK  = COALESCE(#{wonBalAek, jdbcType=NUMERIC}, 0)
     , TAX_AEK      = #{taxAek, jdbcType=NUMERIC}
     , FCUR_TR_AEK  = #{fcurTrAek, jdbcType=NUMERIC}
     , FCUR_BAL_AEK = #{fcurBalAek, jdbcType=NUMERIC}
 WHERE CORP_GR    = #{corpGr, jdbcType=VARCHAR}
   AND TR_YMD     = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD      = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD    = COALESCE(#{origFundCd, jdbcType=VARCHAR}, #{fundCd, jdbcType=VARCHAR})
   AND TRUSTEE    = COALESCE(#{origTrustee, jdbcType=VARCHAR}, #{trustee, jdbcType=VARCHAR})
   AND CURRENCY   = COALESCE(#{origCurrency, jdbcType=VARCHAR}, #{currency, jdbcType=VARCHAR})
   AND TR_SEQ     = COALESCE(#{origTrSeq, jdbcType=NUMERIC}, #{trSeq, jdbcType=NUMERIC})
   AND GYULJE_YMD = TO_DATE(REPLACE(COALESCE(#{origGyuljeYmd, jdbcType=VARCHAR}, #{gyuljeYmd, jdbcType=VARCHAR}), '-', ''), 'YYYYMMDD')
